    // (a Member can't palette-jump to Admin Ops). Server RBAC still governs the actual data.
    ...navDestinations()
      .filter(d => allowed(d.id, visibility))
      .map(d => ({
        id: `go-${d.id}`,
        label: d.labelKey ? t(d.labelKey) : d.label,
