// KR-019 — Article approval panel.
// Shown when an article is IN_REVIEW. Displays approval count badge and
// Approve / Request Changes buttons. Calls the approvals API on click.
// workspace-scoped: articleId is enough; server resolves workspaceId.
import { useState, useEffect } from 'react';
import { CheckCircle, XCircle } from 'lucide-react';
import { api } from '@/lib/apiClient';
import { cn } from '@/lib/utils';

/**
 * @param {{
 *   articleId: string,
 *   requiredApprovals?: number,
 *   currentUserId?: string,
 * }} props
 */
export function ArticleApprovalPanel({ articleId, requiredApprovals = 1, currentUserId }) {
  const [approvals, setApprovals] = useState([]);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);

  const fetchApprovals = () => {
    if (!articleId) return;
    setLoading(true);
    api.send(`/articles/${articleId}/approvals`)
      .then((data) => setApprovals(Array.isArray(data) ? data : []))
      .catch(() => setApprovals([]))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchApprovals();
  }, [articleId]);

  const submit = async (decision) => {
    if (busy) return;
    setBusy(true);
    try {
      await api.send(`/articles/${articleId}/approvals`, {
        method: 'POST',
        body: { decision },
      });
      fetchApprovals();
    } catch { /* error handled at app level */ }
    finally { setBusy(false); }
  };

  const approvedCount = approvals.filter((a) => a.decision === 'APPROVED').length;
  const myApproval = approvals.find((a) => a.reviewerId === currentUserId);

  return (
    <div
      role="region"
      aria-label="Approval panel"
      className="flex items-center gap-3 flex-wrap"
    >
      {/* Approval count badge */}
      <span
        aria-label={`${approvedCount} of ${requiredApprovals} approvals`}
        className={cn(
          'inline-flex items-center gap-1 text-xs font-medium px-2 py-0.5 rounded-full border',
          approvedCount >= requiredApprovals
            ? 'bg-semantic-success/10 border-semantic-success text-semantic-success'
            : 'bg-neutral-100 border-neutral-200 text-neutral-600 dark:bg-neutral-800 dark:border-neutral-700 dark:text-neutral-400',
        )}
      >
        <CheckCircle aria-hidden="true" className="h-3 w-3" />
        {approvedCount}/{requiredApprovals} approved
      </span>

      {loading ? (
        <span className="text-xs text-neutral-400">Loading…</span>
      ) : (
        <>
          <button
            type="button"
            disabled={busy || !!myApproval}
            onClick={() => submit('APPROVED')}
            aria-label="Approve article"
            aria-pressed={myApproval?.decision === 'APPROVED'}
            className={cn(
              'inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-md border transition-colors',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
              'disabled:opacity-50 disabled:cursor-not-allowed',
              myApproval?.decision === 'APPROVED'
                ? 'bg-semantic-success/10 border-semantic-success text-semantic-success'
                : 'border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-semantic-success hover:text-semantic-success',
            )}
          >
            <CheckCircle aria-hidden="true" className="h-3.5 w-3.5" />
            Approve
          </button>

          <button
            type="button"
            disabled={busy || !!myApproval}
            onClick={() => submit('CHANGES_REQUESTED')}
            aria-label="Request changes to article"
            aria-pressed={myApproval?.decision === 'CHANGES_REQUESTED'}
            className={cn(
              'inline-flex items-center gap-1 text-xs px-2.5 py-1 rounded-md border transition-colors',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
              'disabled:opacity-50 disabled:cursor-not-allowed',
              myApproval?.decision === 'CHANGES_REQUESTED'
                ? 'bg-semantic-danger/10 border-semantic-danger text-semantic-danger'
                : 'border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-semantic-danger hover:text-semantic-danger',
            )}
          >
            <XCircle aria-hidden="true" className="h-3.5 w-3.5" />
            Request Changes
          </button>
        </>
      )}
    </div>
  );
}

// Article cover image / gradient banner — shown above the article title in both edit and read
// mode. KR-009 · P0. Stores a gradient key ("gradient:brand-navy-to-orange") or an HTTPS URL.
// 12 preset gradients use only brand + semantic design tokens (RB-30 §2). Image URLs are passed
// through DOMPurify before being set as src to block javascript: and data: schemes (RB-10 §8).
import DOMPurify from 'dompurify';

// Preset gradient options surfaced in the cover picker. Tailwind classes only — no raw hex.
export const COVER_GRADIENTS = {
  'brand-navy-to-ocean':     'bg-gradient-to-r from-brand-navy to-blue-700',
  'brand-orange-to-amber':   'bg-gradient-to-r from-brand-orange to-amber-400',
  'navy-to-orange':          'bg-gradient-to-r from-brand-navy to-brand-orange',
  'teal-to-cyan':            'bg-gradient-to-r from-teal-600 to-cyan-400',
  'purple-to-indigo':        'bg-gradient-to-r from-purple-600 to-indigo-500',
  'green-to-teal':           'bg-gradient-to-r from-semantic-success to-teal-500',
  'danger-to-orange':        'bg-gradient-to-r from-semantic-danger to-brand-orange',
  'neutral-dark':            'bg-gradient-to-r from-neutral-700 to-neutral-500',
  'neutral-light':           'bg-gradient-to-r from-neutral-200 to-neutral-100',
  'blue-sky':                'bg-gradient-to-br from-blue-400 to-cyan-300',
  'sunrise':                 'bg-gradient-to-r from-amber-400 to-pink-400',
  'midnight':                'bg-gradient-to-r from-neutral-900 to-blue-900',
};

/**
 * @param {{ image: string|null }} props
 * image — null → no cover; "gradient:<key>" → CSS gradient; "https://…" → img tag.
 */
export function ArticleCover({ image }) {
  if (!image) return null;

  if (image.startsWith('gradient:')) {
    const key = image.slice('gradient:'.length);
    const cls = COVER_GRADIENTS[key] || 'bg-gradient-to-r from-neutral-300 to-neutral-100';
    return <div className={`h-44 w-full rounded-t-lg ${cls}`} role="img" aria-label="Article cover" />;
  }

  // Sanitise the URL: DOMPurify in FORCE_BODY mode strips dangerous schemes.
  const safe = DOMPurify.sanitize(`<img src="${image}">`, { ALLOWED_TAGS: ['img'], ALLOWED_ATTR: ['src'] });
  const srcMatch = safe.match(/src="([^"]+)"/);
  const safeSrc = srcMatch ? srcMatch[1] : null;

  if (!safeSrc) return null;
  return (
    <img
      src={safeSrc}
      alt=""
      role="presentation"
      className="h-44 w-full object-cover rounded-t-lg"
      onError={(e) => { e.currentTarget.style.display = 'none'; }}
    />
  );
}

// Article icon / emoji picker — KR-010 · P0.
// Displays a clickable icon slot beside the article title. Opens a popover with two tabs:
// a flat emoji grid (40 common emoji) and a small Lucide icon grid. "Clear" resets to the
// template-type default icon. RB-30 §7 minimal UX; WCAG 2.1 AA (all elements labelled).
import { useState, useRef, useEffect } from 'react';
import {
  BookOpen, Terminal, Scale, AlertTriangle, Users, Wrench, FileText,
  LayoutTemplate,
} from 'lucide-react';
import { cn } from '@/lib/utils';

// Default icon per article template type (Lucide component).
export const TEMPLATE_ICONS = {
  KB:               BookOpen,
  RUNBOOK:          Terminal,
  ADR:              Scale,
  POSTMORTEM:       AlertTriangle,
  ONBOARDING:       Users,
  TROUBLESHOOTING:  Wrench,
  CUSTOM:           FileText,
};

const LUCIDE_OPTIONS = [
  { key: 'lucide:FileText',    Icon: FileText },
  { key: 'lucide:BookOpen',    Icon: BookOpen },
  { key: 'lucide:Terminal',    Icon: Terminal },
  { key: 'lucide:Scale',       Icon: Scale },
  { key: 'lucide:AlertTriangle', Icon: AlertTriangle },
  { key: 'lucide:Users',       Icon: Users },
  { key: 'lucide:Wrench',      Icon: Wrench },
  { key: 'lucide:LayoutTemplate', Icon: LayoutTemplate },
];

const COMMON_EMOJI = [
  '📝','📄','📋','📌','📎','🔖','📚','📖',
  '💡','⭐','🔥','✅','❌','⚠️','🚀','🎯',
  '🛠️','🔧','🔍','💬','📊','📈','🗓️','🔔',
  '👥','🤝','💼','🏆','🎉','🧩','🧪','🌐',
  '☁️','🔒','🔑','📡','💾','🖥️','📱','⚡',
];

/**
 * @param {{ icon: string|null, templateType: string, onPick: (icon:string|null)=>void }} props
 */
export function ArticleIconPicker({ icon, templateType, onPick }) {
  const [open, setOpen] = useState(false);
  const [tab, setTab] = useState('emoji');
  const ref = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    const onDown = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    window.addEventListener('keydown', onKey);
    window.addEventListener('pointerdown', onDown);
    return () => { window.removeEventListener('keydown', onKey); window.removeEventListener('pointerdown', onDown); };
  }, [open]);

  const DefaultIcon = TEMPLATE_ICONS[templateType] || FileText;

  const renderSlot = () => {
    if (!icon) return <DefaultIcon aria-hidden="true" className="h-6 w-6 text-neutral-400" />;
    if (icon.startsWith('lucide:')) {
      const found = LUCIDE_OPTIONS.find((o) => o.key === icon);
      const Icon = found ? found.Icon : FileText;
      return <Icon aria-hidden="true" className="h-6 w-6 text-brand-navy dark:text-brand-orange" />;
    }
    return <span className="text-2xl leading-none" aria-hidden="true">{icon}</span>;
  };

  return (
    <div className="relative inline-flex" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-label={`Article icon: ${icon || 'default'}. Click to change.`}
        title="Change article icon"
        className="flex items-center justify-center h-9 w-9 rounded-md hover:bg-neutral-100 dark:hover:bg-neutral-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 transition-colors"
      >
        {renderSlot()}
      </button>

      {open && (
        <div
          role="dialog"
          aria-label="Choose article icon"
          className="absolute left-0 top-full mt-1 z-dropdown w-72 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg shadow-lg p-3 space-y-2"
        >
          <div className="flex items-center gap-2" role="tablist">
            {[{ id: 'emoji', label: 'Emoji' }, { id: 'icons', label: 'Icons' }].map(({ id, label }) => (
              <button
                key={id}
                role="tab"
                aria-selected={tab === id}
                type="button"
                onClick={() => setTab(id)}
                className={cn(
                  'text-xs font-semibold px-2.5 py-1 rounded-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
                  tab === id
                    ? 'bg-brand-navy text-white'
                    : 'text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-800',
                )}
              >
                {label}
              </button>
            ))}
            <button
              type="button"
              onClick={() => { onPick(null); setOpen(false); }}
              className="ml-auto text-xs text-neutral-500 hover:text-semantic-danger focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 rounded"
            >
              Clear
            </button>
          </div>

          {tab === 'emoji' && (
            <div role="tabpanel" aria-label="Emoji" className="grid grid-cols-8 gap-1">
              {COMMON_EMOJI.map((em) => (
                <button
                  key={em}
                  type="button"
                  aria-label={em}
                  onClick={() => { onPick(em); setOpen(false); }}
                  className={cn(
                    'h-8 w-8 text-xl rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
                    icon === em && 'ring-2 ring-brand-navy',
                  )}
                >
                  {em}
                </button>
              ))}
            </div>
          )}

          {tab === 'icons' && (
            <div role="tabpanel" aria-label="Icons" className="grid grid-cols-4 gap-1">
              {LUCIDE_OPTIONS.map(({ key, Icon }) => (
                <button
                  key={key}
                  type="button"
                  aria-label={key.replace('lucide:', '')}
                  onClick={() => { onPick(key); setOpen(false); }}
                  className={cn(
                    'h-10 w-full flex items-center justify-center rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 text-neutral-600 dark:text-neutral-400 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
                    icon === key && 'ring-2 ring-brand-navy text-brand-navy',
                  )}
                >
                  <Icon aria-hidden="true" className="h-5 w-5" />
                </button>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

