// KR-074 — AI grammar & style check panel.
// Shows a list of writing issues found by the server-side heuristic (+ AI when on). Each issue
// has severity (warning / info), the offending text, and a suggestion. An "Accept" button is
// surfaced so the parent can apply the change in the block editor. Design tokens only (RB-30 §1).

import { useState, useEffect } from 'react';
import { X, AlertTriangle, Info, CheckCircle } from 'lucide-react';
import { knowledgeAi } from '@/lib/knowledge-ai';

const SEVERITY_STYLES = {
  warning: {
    icon: AlertTriangle,
    label: 'Warning',
    chip: 'bg-semantic-warning-surface text-semantic-warning',
    iconCls: 'text-semantic-warning',
  },
  info: {
    icon: Info,
    label: 'Info',
    chip: 'bg-brand-navy/10 text-brand-navy',
    iconCls: 'text-brand-navy',
  },
};

/**
 * @param {{ articleText: string, workspaceId: string, open: boolean,
 *           onClose: () => void, onAcceptIssue: (issue: object) => void }} props
 */
export function CheckWritingPanel({ articleText, workspaceId, open, onClose, onAcceptIssue }) {
  const [issues, setIssues] = useState([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [dismissed, setDismissed] = useState(new Set());

  // Re-check whenever the panel is opened or articleText changes significantly.
  useEffect(() => {
    if (!open || !workspaceId || !articleText?.trim()) {
      setIssues([]);
      return;
    }
    let cancelled = false;
    setBusy(true);
    setError(null);
    setDismissed(new Set());
    knowledgeAi.checkWriting(workspaceId, articleText)
      .then((res) => {
        if (!cancelled) setIssues(Array.isArray(res) ? res : []);
      })
      .catch(() => {
        if (!cancelled) setError('Could not check writing. Try again.');
      })
      .finally(() => {
        if (!cancelled) setBusy(false);
      });
    return () => { cancelled = true; };
  }, [open]);

  if (!open) return null;

  const visible = issues.filter((_, i) => !dismissed.has(i));

  return (
    <aside
      aria-label="Writing check"
      className="w-72 flex-shrink-0 border-l border-neutral-200 dark:border-neutral-700 bg-neutral-50 dark:bg-neutral-900 overflow-y-auto flex flex-col"
    >
      {/* Panel header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-neutral-200 dark:border-neutral-700">
        <h3 className="text-xs font-semibold text-neutral-500 dark:text-neutral-400 uppercase tracking-wider">
          Writing check
        </h3>
        <button
          type="button"
          aria-label="Close writing check panel"
          onClick={onClose}
          className="p-0.5 rounded text-neutral-400 hover:text-neutral-700 dark:hover:text-neutral-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40"
        >
          <X className="h-3.5 w-3.5" aria-hidden="true" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-3">
        {busy && (
          <div className="space-y-2" aria-busy="true" aria-label="Checking writing…">
            {[0, 1, 2].map((i) => (
              <div key={i} className="h-16 rounded-lg animate-pulse bg-neutral-100 dark:bg-neutral-700" />
            ))}
          </div>
        )}

        {error && (
          <p role="alert" className="text-xs text-semantic-danger">{error}</p>
        )}

        {!busy && !error && visible.length === 0 && (
          <div className="flex flex-col items-center gap-2 py-8 text-center">
            <CheckCircle className="h-8 w-8 text-semantic-success" aria-hidden="true" />
            <p className="text-xs font-semibold text-neutral-700 dark:text-neutral-300">
              {issues.length === 0 ? 'No issues found.' : 'All issues resolved.'}
            </p>
          </div>
        )}

        {!busy && visible.map((issue, i) => {
          const sev = SEVERITY_STYLES[issue.severity] || SEVERITY_STYLES.info;
          const SevIcon = sev.icon;
          const realIndex = issues.findIndex((iss, idx) => iss === issue && !dismissed.has(idx));
          return (
            <div
              key={i}
              className="bg-white dark:bg-neutral-800 rounded-lg border border-neutral-200 dark:border-neutral-700 p-3 space-y-2"
            >
              <div className="flex items-start gap-2">
                <SevIcon
                  aria-hidden="true"
                  className={`h-3.5 w-3.5 mt-0.5 flex-shrink-0 ${sev.iconCls}`}
                />
                <div className="flex-1 min-w-0">
                  <code className="text-xs bg-neutral-100 dark:bg-neutral-700 px-1 py-0.5 rounded font-mono text-neutral-800 dark:text-neutral-200 truncate block">
                    {issue.text}
                  </code>
                  <p className="text-xs text-neutral-700 dark:text-neutral-300 mt-1">
                    {issue.suggestion}
                  </p>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span className={`text-xs font-semibold px-1.5 py-0.5 rounded ${sev.chip}`}>
                  {sev.label}
                </span>
                <div className="flex gap-1.5 ml-auto">
                  <button
                    type="button"
                    onClick={() => onAcceptIssue?.(issue)}
                    className="text-xs text-brand-navy hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 rounded"
                  >
                    Accept
                  </button>
                  <button
                    type="button"
                    onClick={() => setDismissed((prev) => new Set([...prev, realIndex >= 0 ? realIndex : i]))}
                    className="text-xs text-neutral-400 hover:text-neutral-600 dark:hover:text-neutral-300 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 rounded"
                  >
                    Dismiss
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </aside>
  );
}

// KR-030 — Knowledge workspace settings panel.
// Lets workspace admins configure the comment digest frequency.
import { useState, useEffect } from 'react';
import { Bell, Loader } from 'lucide-react';
import { api } from '@/lib/apiClient';
import { cn } from '@/lib/utils';
import { pushToast } from '@/lib/toast-queue';

const FREQUENCIES = [
  { value: 'off',    label: 'Off' },
  { value: 'daily',  label: 'Daily' },
  { value: 'weekly', label: 'Weekly' },
];

/**
 * @param {{
 *   workspaceId: string,
 *   canManage: boolean,
 * }} props
 */
export function KnowledgeSettingsPanel({ workspaceId, canManage = false }) {
  const [frequency, setFrequency] = useState('off');
  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!workspaceId) return;
    setLoading(true);
    api.send(`/workspaces/${workspaceId}/settings/knowledge/comment-digest`)
      .then((data) => setFrequency(data.frequency || 'off'))
      .catch((e) => setError(e.message || 'Failed to load settings'))
      .finally(() => setLoading(false));
  }, [workspaceId]);

  async function handleChange(newFreq) {
    if (!canManage || newFreq === frequency) return;
    setSaving(true);
    setError(null);
    try {
      const data = await api.send(
        `/workspaces/${workspaceId}/settings/knowledge/comment-digest`,
        { method: 'PATCH', body: { frequency: newFreq } },
      );
      setFrequency(data.frequency || newFreq);
      pushToast({ message: 'Comment digest settings saved', tone: 'success' });
    } catch (e) {
      setError(e.message || 'Failed to save settings');
      pushToast({ message: 'Failed to save comment digest settings', tone: 'danger' });
    } finally {
      setSaving(false);
    }
  }

  return (
    <section aria-labelledby="know-settings-title" className="space-y-4">
      <div className="flex items-center gap-2">
        <Bell className="h-5 w-5 text-brand-navy" aria-hidden="true" />
        <h3 id="know-settings-title" className="text-base font-semibold text-neutral-900 dark:text-neutral-100">
          Comment digest
        </h3>
      </div>

      <p className="text-sm text-neutral-600 dark:text-neutral-400">
        Send article authors a digest of new block comments at the chosen frequency.
        {!canManage && (
          <span className="ml-1 text-neutral-400">(Requires workspace admin access to change.)</span>
        )}
      </p>

      {loading ? (
        <div className="flex items-center gap-2 text-sm text-neutral-500" aria-live="polite" aria-busy="true">
          <Loader className="h-4 w-4 animate-spin" aria-hidden="true" />
          Loading…
        </div>
      ) : (
        <div className="flex items-center gap-3" role="group" aria-label="Comment digest frequency">
          {FREQUENCIES.map(({ value, label }) => (
            <button
              key={value}
              type="button"
              disabled={!canManage || saving}
              aria-pressed={frequency === value}
              onClick={() => handleChange(value)}
              className={cn(
                'px-3 py-1.5 rounded-lg border text-sm transition-colors',
                'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
                'disabled:opacity-50 disabled:cursor-not-allowed',
                'active:translate-y-px',
                frequency === value
                  ? 'bg-brand-navy text-white border-brand-navy'
                  : 'border-neutral-200 dark:border-neutral-700 text-neutral-600 dark:text-neutral-400 hover:border-brand-navy hover:text-brand-navy',
              )}
            >
              {saving && frequency !== value ? label : label}
            </button>
          ))}
          {saving && (
            <Loader className="h-4 w-4 animate-spin text-neutral-400" aria-label="Saving…" />
          )}
        </div>
      )}

      {error && (
        <p role="alert" className="text-sm text-semantic-danger">
          {error}
        </p>
      )}
    </section>
  );
}

// KR-028 — @mention picker for comment textareas.
// Triggers when the user types "@" at a word boundary. Fetches workspace members,
// filters by typed query. Selecting inserts "@username" at cursor position.
// Closes on Escape or outside click. Renders as a floating dropdown below the caret.
import { useState, useEffect, useRef, useCallback } from 'react';
import { api } from '@/lib/apiClient';

const MENTION_RE = /@(\w*)$/;

function getMentionQuery(textarea) {
  const val = textarea.value;
  const pos = textarea.selectionStart;
  const textBefore = val.slice(0, pos);
  const match = MENTION_RE.exec(textBefore);
  return match ? match[1] : null;
}

/**
 * Wrap a comment textarea to support @mention picks.
 *
 * @param {{
 *   workspaceId: string,
 *   children: (props: { ref: Ref, onChange: fn, onKeyDown: fn }) => ReactElement,
 *   value: string,
 *   onChange: (value: string) => void,
 * }} props
 */
export function MentionPicker({ workspaceId, onChange, children }) {
  const [members, setMembers] = useState([]);
  const [query, setQuery] = useState(null);
  const [open, setOpen] = useState(false);
  const [selected, setSelected] = useState(0);
  const textareaRef = useRef(null);
  const containerRef = useRef(null);

  // Fetch members once when workspaceId is known
  useEffect(() => {
    if (!workspaceId) return;
    api.send(`/workspaces/${encodeURIComponent(workspaceId)}/members`)
      .then(data => setMembers(Array.isArray(data) ? data : []))
      .catch(() => setMembers([]));
  }, [workspaceId]);

  // Close on outside click
  useEffect(() => {
    if (!open) return undefined;
    const onDown = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) setOpen(false);
    };
    window.addEventListener('pointerdown', onDown);
    return () => window.removeEventListener('pointerdown', onDown);
  }, [open]);

  const filtered = members.filter(m => {
    if (query === null || query === '') return members.slice(0, 8);
    const q = query.toLowerCase();
    return (m.name || m.email || m.id || '').toLowerCase().includes(q);
  }).slice(0, 8);

  const insertMention = useCallback((member) => {
    const ta = textareaRef.current;
    if (!ta) return;
    const pos = ta.selectionStart;
    const val = ta.value;
    const textBefore = val.slice(0, pos);
    const match = MENTION_RE.exec(textBefore);
    if (!match) return;
    const mentionStart = pos - match[0].length;
    const username = member.name || member.email || member.id;
    const newVal = val.slice(0, mentionStart) + `@${username} ` + val.slice(pos);
    onChange(newVal);
    setOpen(false);
    setQuery(null);
    // Move caret after the inserted mention
    requestAnimationFrame(() => {
      if (!textareaRef.current) return;
      const newPos = mentionStart + username.length + 2; // "@" + username + " "
      textareaRef.current.setSelectionRange(newPos, newPos);
      textareaRef.current.focus();
    });
  }, [onChange]);

  const handleChange = useCallback((e) => {
    const val = e.target.value;
    onChange(val);
    const q = getMentionQuery(e.target);
    if (q !== null) {
      setQuery(q);
      setSelected(0);
      setOpen(true);
    } else {
      setOpen(false);
      setQuery(null);
    }
  }, [onChange]);

  const handleKeyDown = useCallback((e) => {
    if (!open) return;
    if (e.key === 'ArrowDown') { e.preventDefault(); setSelected(s => Math.min(s + 1, filtered.length - 1)); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); setSelected(s => Math.max(s - 1, 0)); }
    else if (e.key === 'Enter' || e.key === 'Tab') {
      if (filtered[selected]) { e.preventDefault(); insertMention(filtered[selected]); }
    }
    else if (e.key === 'Escape') { setOpen(false); setQuery(null); }
  }, [open, filtered, selected, insertMention]);

  return (
    <div ref={containerRef} className="relative">
      {children({ ref: textareaRef, onChange: handleChange, onKeyDown: handleKeyDown })}

      {open && filtered.length > 0 && (
        <ul
          role="listbox"
          aria-label="Mention members"
          className="absolute left-0 bottom-full mb-1 z-dropdown w-56 bg-white dark:bg-neutral-900 border border-neutral-200 dark:border-neutral-700 rounded-lg shadow-lg py-1 max-h-48 overflow-y-auto"
        >
          {filtered.map((m, i) => {
            const display = m.name || m.email || m.id || 'Unknown';
            return (
              <li
                key={m.id || m.email || i}
                role="option"
                aria-selected={i === selected}
                onMouseDown={(e) => { e.preventDefault(); insertMention(m); }}
                className={`flex items-center gap-2 px-3 py-1.5 text-xs cursor-pointer ${i === selected ? 'bg-brand-navy/10 text-brand-navy' : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-800'}`}
              >
                <span className="h-5 w-5 rounded-full bg-brand-navy/20 flex items-center justify-center text-brand-navy font-semibold text-xs flex-shrink-0">
                  {display[0].toUpperCase()}
                </span>
                <span className="truncate">{display}</span>
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

/** Render @username mentions in brand-orange in HTML content. */
export function renderMentions(text) {
  if (!text) return '';
  return text.replace(/@(\w+)/g, '<span class="text-brand-orange font-medium">@$1</span>');
}

