const ATTENTION_TONE = {
  danger: { dot: 'bg-semantic-danger', text: 'text-semantic-danger', icon: AlertTriangle },
  warning: { dot: 'bg-semantic-warning', text: 'text-semantic-warning', icon: AlertTriangle },
  neutral: { dot: 'bg-brand-navy-tint', text: 'text-brand-navy dark:text-brand-navy-tint', icon: Sparkles },
};

const SOURCE_LABELS = {
  myworks: 'Assigned work',
  board: 'Delivery board',
  sprint: 'Active sprint',
  backlog: 'Product backlog',
  releases: 'Release plan',
  projects: 'Project portfolio',
  reports: 'Risk register',
  workspace: 'Workspace posture',
  security: 'Security audit',
  supportinbox: 'Support inbox',
  developer: 'DevSync',
  knowledge: 'Knowledge review',
  sla: 'SLA monitor',
};

function DailyClarityBand({ brief, onNavigate, onSnooze, onDismiss }) {
  if (!brief) return null;
  const attentionCount = brief.attention.length;
  const newCount = brief.attention.filter((item) => item.isNew).length;

  return (
    <Card as="section" padding="none" aria-labelledby="daily-clarity-heading"
      className="mb-6 rounded-lg border border-neutral-200 bg-white p-5 shadow-sm dark:border-neutral-700 dark:bg-neutral-800">
      <div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between">
        <div className="max-w-2xl">
          <p className="text-xs font-semibold uppercase tracking-wide text-neutral-500 dark:text-neutral-400">
            {brief.dateLabel} - {brief.roleLabel}
          </p>
          <h2 id="daily-clarity-heading" className="mt-1 text-2xl font-bold text-neutral-950 dark:text-neutral-50">
            Daily clarity
          </h2>
          <p className="mt-2 text-sm text-neutral-600 dark:text-neutral-300">{brief.confidence}</p>
        </div>

        <div className="flex flex-wrap gap-2">
          <Button unstyled type="button" onClick={() => onNavigate?.(brief.primaryAction.view)}
            className="inline-flex items-center gap-2 rounded-lg bg-brand-navy px-3.5 py-2 text-sm font-semibold text-white transition-colors duration-fast hover:bg-brand-navy/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40">
            {brief.primaryAction.label}
            <ArrowRight className="h-4 w-4" aria-hidden="true" />
          </Button>
          {brief.secondaryAction && (
            <Button unstyled type="button" onClick={() => onNavigate?.(brief.secondaryAction.view)}
              className="inline-flex items-center gap-2 rounded-lg border border-neutral-200 px-3.5 py-2 text-sm font-semibold text-neutral-700 transition-colors duration-fast hover:bg-neutral-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 dark:border-neutral-700 dark:text-neutral-200 dark:hover:bg-neutral-700">
              {brief.secondaryAction.label}
            </Button>
          )}
        </div>
      </div>

      <div className="mt-5 grid gap-4 lg:grid-cols-[minmax(0,1fr)_18rem]">
        <div>
          <div className="mb-3 flex items-center justify-between gap-3">
            <h3 className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">Needs attention</h3>
            <div className="flex items-center gap-2 text-xs font-medium text-neutral-500 dark:text-neutral-400">
              {newCount > 0 && <span className="text-brand-navy dark:text-brand-navy-tint">{newCount} new since last visit</span>}
              <span>{attentionCount} of {brief.attentionLimit}</span>
            </div>
          </div>
          {attentionCount > 0 ? (
            <ul className="grid gap-2 md:grid-cols-2">
              {brief.attention.map((item) => {
                const tone = ATTENTION_TONE[item.tone] || ATTENTION_TONE.neutral;
                const Icon = tone.icon;
                return (
                  <li key={item.attentionKey || item.id} className="rounded-lg border border-neutral-100 bg-neutral-50 p-3 dark:border-neutral-700 dark:bg-neutral-900">
                    <div className="flex items-start gap-3">
                      <span className={`mt-1 h-2.5 w-2.5 rounded-full ${tone.dot}`} aria-hidden="true" />
                      <div className="min-w-0 flex-1">
                        <div className="flex min-w-0 items-center gap-2">
                          <p className="truncate text-sm font-semibold text-neutral-900 dark:text-neutral-100">{item.title}</p>
                          {item.isNew && (
                            <span className="rounded bg-brand-navy/10 px-1.5 py-0.5 text-2xs font-semibold text-brand-navy dark:text-brand-navy-tint">
                              New
                            </span>
                          )}
                        </div>
                        <p className="mt-1 text-xs text-neutral-600 dark:text-neutral-400">{item.reason}</p>
                      </div>
                      <Icon className={`h-4 w-4 flex-shrink-0 ${tone.text}`} aria-hidden="true" />
                    </div>
                    <div className="mt-3 flex items-center justify-between gap-2 border-t border-neutral-200 pt-2 dark:border-neutral-700">
                      <span className="truncate text-2xs text-neutral-500">
                        Source: {SOURCE_LABELS[item.view] || 'Workspace signal'}
                      </span>
                      <div className="flex flex-shrink-0 items-center gap-1">
                        <Button type="button" variant="ghost" size="icon" title="Snooze until tomorrow"
                          aria-label={`Snooze ${item.title} until tomorrow`} onClick={() => onSnooze?.(item)}
                          className="h-8 w-8">
                          <Clock3 className="h-3.5 w-3.5" aria-hidden="true" />
                        </Button>
                        <Button type="button" variant="ghost" size="icon" title="Dismiss"
                          aria-label={`Dismiss ${item.title}`} onClick={() => onDismiss?.(item)}
                          className="h-8 w-8">
                          <X className="h-3.5 w-3.5" aria-hidden="true" />
                        </Button>
                        <Button type="button" variant="secondary" size="sm" onClick={() => onNavigate?.(item.view)}>
                          Open
                          <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
                        </Button>
                      </div>
                    </div>
                  </li>
                );
              })}
            </ul>
          ) : (
            <div className="rounded-lg border border-semantic-success/20 bg-semantic-success/10 p-4">
              <div className="flex items-center gap-2 text-sm font-semibold text-semantic-success">
                <CheckCircle2 className="h-4 w-4" aria-hidden="true" />
                Quiet win
              </div>
              <p className="mt-1 text-sm text-neutral-700 dark:text-neutral-300">{brief.quietWin}</p>
            </div>
          )}
        </div>

        <aside className="rounded-lg border border-neutral-100 bg-neutral-50 p-4 dark:border-neutral-700 dark:bg-neutral-900">
          <p className="text-xs font-semibold uppercase tracking-wide text-neutral-500 dark:text-neutral-400">Suggested next action</p>
          <p className="mt-2 text-sm font-semibold text-neutral-900 dark:text-neutral-100">{brief.primaryAction.label}</p>
          <p className="mt-1 text-xs text-neutral-600 dark:text-neutral-400">
            Start from the most constrained signal, then let the detailed Today canvas handle the rest of the day.
          </p>
        </aside>
      </div>
    </Card>
  );
}

export default function DashboardView({
  currentUser,
  activeWorkspaceId,
  userRole,
  dashboardRole,
  dashLoading,
  developerDash,
  smDash,
  poDash,
  supportDash,
  execDash,
  adminDash,
  workItems,
  selectedItem,
  setIsCreateOpen,
  setDashboardRole,
  fetchDashboard,
  setView,
  setSelectedItem,
  setIsWorklogOpen,
  showToast,
  todayLayout,
  saveTodayLayout,
  resetTodayLayout,
  saveTodayTemplate,
  fetchWidgetData,
  previewWidgetData,
  widgetMetrics,
}) {
  // Resolve the data for the active role and auto-fetch if not yet loaded
  const DATA_MAP = {
    'developer':     developerDash,
    'scrum-master':  smDash,
    'product-owner': poDash,
    'support-agent': supportDash,
    'executive':     execDash,
    'admin':         adminDash,
  };
  const activeData = DATA_MAP[dashboardRole] ?? null;

  const attentionStoreKey = todayAttentionKey(activeWorkspaceId, currentUser?.id, dashboardRole);
  const [attentionContext, setAttentionContext] = useState(attentionStoreKey);
  const [attentionState, setAttentionState] = useState(() => readTodayAttention(attentionStoreKey));
  if (attentionContext !== attentionStoreKey) {
    setAttentionContext(attentionStoreKey);
    setAttentionState(readTodayAttention(attentionStoreKey));
  }

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState([]);
  // A draft is per-role; leaving a role exits edit mode. Reset during render (not in an effect)
  // using the previous-value idiom so the role's own data and draft never get out of sync.
  const [prevRole, setPrevRole] = useState(dashboardRole);
  if (prevRole !== dashboardRole) {
    setPrevRole(dashboardRole);
    setEditing(false);
  }

  useEffect(() => {
    if (!activeData && !dashLoading) {
      fetchDashboard(dashboardRole);
    }
  }, [dashboardRole]); // activeData/dashLoading excluded: including them would trigger a loop on every fetch.

  const switchRole = (role) => {
    setDashboardRole(role);
    fetchDashboard(role);
  };

  // Effective layout: the saved personal/workspace layout for THIS role, else the built-in default.
  const savedForRole = todayLayout?.role === dashboardRole ? todayLayout : null;
  const savedLayout = savedForRole?.widgets ? widgetsToLayout(savedForRole.widgets) : null;
  const builtin = builtinTodayLayout(dashboardRole, activeData);
  const resolved = savedLayout ?? builtin;

  const clone = (l) => l.map((w) => ({ ...w, config: { ...w.config } }));
  const swap = (l, i, j) => {
    if (j < 0 || j >= l.length) return l;
    const c = [...l];
    [c[i], c[j]] = [c[j], c[i]];
    return c;
  };

  const edit = {
    editing,
    source: savedForRole?.source || 'builtin',
    draft,
    start: () => { setDraft(clone(resolved)); setEditing(true); },
    cancel: () => setEditing(false),
    save: () => { saveTodayLayout?.(dashboardRole, draft); setEditing(false); },
    reset: () => { resetTodayLayout?.(dashboardRole); setEditing(false); },
    // Admin/Owner only: set the workspace-wide default for this role (slice 6). Visibility gate
    // only — the server re-checks manage_workspace (RB-40 §1).
    canTemplate: (userRole?.tier ?? 0) >= TIER.ADMIN,
    saveTemplate: () => { saveTodayTemplate?.(dashboardRole, draft); setEditing(false); },
    add: (w) => setDraft((d) => [...d, { ...w, config: { ...w.config } }]),
    remove: (i) => setDraft((d) => d.filter((_, j) => j !== i)),
    moveUp: (i) => setDraft((d) => swap(d, i, i - 1)),
    moveDown: (i) => setDraft((d) => swap(d, i, i + 1)),
    cycleSpan: (i) => setDraft((d) => d.map((w, j) => (j === i ? { ...w, span: nextSpan(w.span || 12) } : w))),
    // Data-widget tooling (slice 5): batch-resolve, live preview, and the metric catalogue.
    widgetTools: { fetchWidgetData, previewWidgetData, metrics: widgetMetrics || [] },
  };

  const sharedProps = {
    currentUser, activeWorkspaceId, setView, setIsCreateOpen, setSelectedItem, setIsWorklogOpen, selectedItem,
    showToast, workItems, layout: resolved, builtinLayout: builtin, edit,
  };
  const rawTodayBrief = activeData ? buildTodayBrief(dashboardRole, activeData) : null;
  const todayBrief = rawTodayBrief ? {
    ...rawTodayBrief,
    attention: visibleTodayAttention(rawTodayBrief.attention, attentionState),
  } : null;
  const attentionSnapshotKey = rawTodayBrief?.attention
    .map((item) => `${item.id}:${item.title}:${item.reason}`).join('|') || '';
  useEffect(() => {
    if (!rawTodayBrief) return;
    writeTodayAttention(attentionStoreKey,
      snapshotTodayAttention(attentionState, rawTodayBrief.attention));
    // The in-memory state intentionally stays unchanged so "New" remains visible for this visit.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [attentionStoreKey, attentionSnapshotKey]);

  const updateAttentionState = (next, message) => {
    setAttentionState(next);
    writeTodayAttention(attentionStoreKey, next);
    showToast?.(message);
  };
  const snoozeAttention = (item) => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    tomorrow.setHours(8, 0, 0, 0);
    updateAttentionState(snoozeTodayAttention(attentionState, item, tomorrow), 'Snoozed until tomorrow');
  };
  const dismissAttention = (item) => {
    updateAttentionState(dismissTodayAttention(attentionState, item), 'Dismissed from Today');
  };
  const openAiSource = (id, title) => {
    if (id) setSelectedItem?.({ id, title });
    setView?.('myworks');
  };
  const roleDashboard = dashboardRole === 'scrum-master'  ? <ScrumMasterToday  data={smDash}       {...sharedProps} />
    : dashboardRole === 'product-owner' ? <ProductOwnerToday data={poDash}       {...sharedProps} />
    : dashboardRole === 'support-agent' ? <SupportAgentToday data={supportDash}  {...sharedProps} />
    : dashboardRole === 'executive'     ? <ExecutiveToday    data={execDash}     {...sharedProps} />
    : dashboardRole === 'admin'         ? <AdminToday        data={adminDash}    {...sharedProps} />
    :                                     <DeveloperToday    data={developerDash} {...sharedProps} />;

  return (
    <PageLayout header={null}>
      <RoleTabs dashboardRole={dashboardRole} onSwitch={switchRole} userRole={userRole} />

      {dashLoading || !activeData
        ? <TodaySkeleton />
        : (
          <>
            <TodayAiBrief workspaceId={activeWorkspaceId} onOpenItem={openAiSource} />
            <DailyClarityBand brief={todayBrief} onNavigate={setView}
              onSnooze={snoozeAttention} onDismiss={dismissAttention} />
            {roleDashboard}
          </>
        )
      }
    </PageLayout>
  );
}

import { Table } from '@/components/works/atoms/table';
import { useEffect, useState } from 'react';
import { Button } from '@/components/works/button';
import { StatusBadge } from '@/components/works/status-badge';
import { statusToCategory } from '@/components/works/status';
import { DonutChart, BarChart } from '@/components/works/molecules';
import { TodayCanvas } from '@/components/works/organisms/today-canvas';
import { TodayWidgetPicker } from '@/components/works/organisms/today-widget-picker';
import { ArrowRight, Users, BarChart2, Pencil, Check, RotateCcw, Plus } from 'lucide-react';

// ── Shared atoms ──────────────────────────────────────────────────────────────

export function TodayCard({ title, icon: Icon, iconColor, action, actionLabel, children, className }) {
  return (
    <div className={`rounded-xl border border-neutral-200 bg-white dark:border-neutral-700 dark:bg-neutral-800 ${className || ''}`}>
      <div className="flex items-center justify-between border-b border-neutral-100 px-5 py-3 dark:border-neutral-700">
        <h3 className="flex items-center gap-2 font-semibold text-neutral-900 dark:text-neutral-100">
          {Icon && <Icon className={`h-4 w-4 ${iconColor || 'text-neutral-500'}`} aria-hidden="true" />}
          {title}
        </h3>
        {action && (
          <Button unstyled type="button" onClick={action}
            className="flex items-center gap-1 text-xs text-brand-navy hover:underline focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 rounded">
            {actionLabel || 'View all'}
            <ArrowRight className="h-3.5 w-3.5" aria-hidden="true" />
          </Button>
        )}
      </div>
      <div className="px-5 py-4">{children}</div>
    </div>
  );
}

export function HealthRing({ pct, size = 80, stroke = 'stroke-semantic-success', label }) {
  const safe = Math.min(100, Math.max(0, pct || 0));
  return (
    <div className="relative flex-shrink-0" style={{ width: size, height: size }}>
      <svg viewBox="0 0 36 36" className="-rotate-90" style={{ width: size, height: size }} aria-hidden="true">
        <circle cx="18" cy="18" r="15.9" fill="none" pathLength="100"
          className="stroke-neutral-100 dark:stroke-neutral-700" strokeWidth="3" />
        <circle cx="18" cy="18" r="15.9" fill="none" pathLength="100"
          className={stroke} strokeWidth="3" strokeLinecap="round"
          strokeDasharray={`${safe} 100`} />
      </svg>
      <div className="absolute inset-0 flex flex-col items-center justify-center text-center leading-none">
        <span className="text-sm font-bold text-neutral-900 dark:text-neutral-100">{safe}%</span>
        {label && <span className="mt-0.5 text-2xs text-neutral-500">{label}</span>}
      </div>
    </div>
  );
}

export function MiniBar({ value, max, color = 'bg-brand-navy' }) {
  const pct = max > 0 ? Math.min(100, Math.round((value || 0) * 100 / max)) : 0;
  return (
    <div className="h-2 w-full rounded-full bg-neutral-100 dark:bg-neutral-700">
      <div className={`h-2 rounded-full transition-all duration-base ${color}`} style={{ width: `${pct}%` }} />
    </div>
  );
}

export function Empty({ msg }) {
  return <p className="py-8 text-center text-sm text-neutral-500 dark:text-neutral-400">{msg}</p>;
}

function TodayHeader({ greeting, firstName, rolePill, subtitle, cta, onCta }) {
  return (
    <div className="mb-6 flex flex-wrap items-start justify-between gap-3">
      <div>
        <div className="flex flex-wrap items-center gap-2.5">
          <h1 className="text-2xl font-bold text-brand-navy dark:text-white">
            Good {greeting}, {firstName}
          </h1>
          {rolePill && (
            <span className="rounded-full bg-brand-navy/10 px-2.5 py-0.5 text-xs font-semibold text-brand-navy dark:bg-neutral-700 dark:text-neutral-200">
              {rolePill}
            </span>
          )}
        </div>
        <p className="mt-0.5 text-sm text-neutral-600 dark:text-neutral-400">{subtitle}</p>
      </div>
      {cta && <Button variant="action" onClick={onCta}>{cta}</Button>}
    </div>
  );
}


// ── Today surface — header + edit toolbar + canvas ─────────────────────────────
// Wraps every role's Today: renders the fixed header, the customize/edit controls, and the
// TodayCanvas. Editing happens on a draft layout owned by DashboardView (so Save/Cancel span the
// toolbar); this component only presents it. Built-in default ⇄ personalized is shown as a pill.

// Friendly label for a widget in the "Add" menu — stat widgets name their KPI; others title-case.
function widgetLabel(w) {
  if (w.type === 'stat') return `KPI · ${w.config?.k ?? 'metric'}`;
  return w.type.replace(/-/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

// Renders a configured data widget's result per its viz (slice 5). Result comes from the
// /widget-data executor: { shape, value | series | rows } or { error }.
function renderDataViz(viz, result) {
  if (viz === 'scorecard') {
    return <p className="text-3xl font-bold text-brand-navy dark:text-white">{result.value ?? result.series?.length ?? result.rows?.length ?? 0}</p>;
  }
  if (viz === 'bar') return <BarChart data={(result.series || []).map((s) => ({ label: String(s.label), value: Number(s.value) }))} />;
  if (viz === 'donut') return <DonutChart data={(result.series || []).map((s) => ({ label: String(s.label), value: Number(s.value) }))} />;
  const rows = result.rows || [];
  if (!rows.length) return <Empty msg="No matching items." />;
  return (
    <Table className="w-full text-sm">
      <tbody className="divide-y divide-neutral-100 dark:divide-neutral-700">
        {rows.slice(0, 8).map((r) => (
          <tr key={r.id}>
            <td className="py-2 pr-2"><span className="flex min-w-0 items-center gap-2">
              <span className="flex-shrink-0 font-mono text-xs text-neutral-400">{r.id}</span>
              <span className="truncate text-neutral-900 dark:text-neutral-100">{r.title}</span>
            </span></td>
            <td className="py-2 text-right">{r.status && <StatusBadge category={statusToCategory(r.status)}>{r.status}</StatusBadge>}</td>
          </tr>
        ))}
      </tbody>
    </Table>
  );
}

// Generic registry merged into every role's registry, so a saved layout's `data` widgets render
// regardless of which role is active. The widget's result is supplied via ctx.widgetData[id].
const GENERIC_DATA_REGISTRY = {
  data: (ctx, w) => {
    const cfg = w.config || {};
    const result = ctx.widgetData?.[w.id];
    return (
      <TodayCard title={cfg.title || 'Widget'} icon={BarChart2} iconColor="text-brand-navy">
        {!result
          ? <div className="h-16 animate-pulse rounded bg-neutral-100 dark:bg-neutral-800" />
          : result.error
            ? <Empty msg={result.error} />
            : renderDataViz(cfg.viz, result)}
      </TodayCard>
    );
  },
};

function AddWidgetMenu({ addable, onAdd, onNew }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative">
      <Button unstyled type="button" onClick={() => setOpen((o) => !o)}
        aria-haspopup="menu" aria-expanded={open}
        className="flex items-center gap-1 rounded-md border border-neutral-200 bg-white px-2.5 py-1.5 text-xs font-medium text-neutral-700 transition-colors hover:border-brand-navy hover:text-brand-navy focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40 dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-300">
        <Plus className="h-3.5 w-3.5" aria-hidden="true" />Add widget
      </Button>
      {open && (
        <div role="menu"
          className="absolute right-0 z-dropdown mt-1 max-h-64 w-56 overflow-auto rounded-lg border border-neutral-200 bg-white py-1 shadow-lg dark:border-neutral-700 dark:bg-neutral-800">
          <Button unstyled type="button" role="menuitem"
            onClick={() => { onNew(); setOpen(false); }}
            className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs font-semibold text-brand-navy hover:bg-neutral-100 focus-visible:outline-none focus-visible:bg-neutral-100 dark:text-neutral-200 dark:hover:bg-neutral-700">
            <Plus className="h-3.5 w-3.5 flex-shrink-0" aria-hidden="true" />New data widget…
          </Button>
          {addable.length > 0 && (
            <>
              <div className="my-1 border-t border-neutral-100 dark:border-neutral-700" />
              <p className="px-3 py-1 text-2xs font-semibold uppercase tracking-wide text-neutral-400">Re-add default</p>
              {addable.map((w) => (
                <Button unstyled key={w.id} type="button" role="menuitem"
                  onClick={() => { onAdd(w); setOpen(false); }}
                  className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-neutral-700 hover:bg-neutral-100 focus-visible:outline-none focus-visible:bg-neutral-100 dark:text-neutral-300 dark:hover:bg-neutral-700">
                  <Plus className="h-3.5 w-3.5 flex-shrink-0 text-neutral-400" aria-hidden="true" />
                  {widgetLabel(w)}
                </Button>
              ))}
            </>
          )}
        </div>
      )}
    </div>
  );
}

export function TodaySurface({ header, registry, ctx, layout, builtinLayout, edit }) {
  const editing = edit?.editing;
  const shown = editing ? edit.draft : layout;
  const addable = editing ? builtinLayout.filter((b) => !edit.draft.some((d) => d.id === b.id)) : [];
  const tbtn = 'flex items-center gap-1 rounded-md border px-2.5 py-1.5 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40';
  const tools = edit?.widgetTools;

  // Batch-resolve every `data` widget in one round trip (NFR: one call, not one per widget).
  const [widgetData, setWidgetData] = useState({});
  const [pickerOpen, setPickerOpen] = useState(false);
  const dataWidgets = shown.filter((w) => w.type === 'data' && w.config?.source);
  const dataKey = JSON.stringify(dataWidgets.map((w) => [w.id, w.config.source]));
  useEffect(() => {
    if (!dataWidgets.length || !tools?.fetchWidgetData) return undefined;
    const items = {};
    dataWidgets.forEach((w) => { items[w.id] = w.config.source; });
    let cancelled = false;
    tools.fetchWidgetData(items)
      .then((results) => {
        if (cancelled) return;
        const map = {};
        (results || []).forEach((r) => { map[r.id] = r.data ? r.data : { error: r.error || 'No data' }; });
        setWidgetData(map);
      })
      .catch(() => { if (!cancelled) setWidgetData({}); });
    return () => { cancelled = true; };
  }, [dataKey]); // api.send, widgetSpecs, setWidgetData excluded: stable refs that don't affect when to re-fetch.

  const fullRegistry = { ...GENERIC_DATA_REGISTRY, ...registry };
  const fullCtx = { ...ctx, widgetData };

  return (
    <>
      <TodayHeader {...header} />
      {edit && (
        <div className="mb-4 flex flex-wrap items-center justify-end gap-2">
          {!editing && edit.source !== 'builtin' && (
            <span className="mr-auto rounded-full bg-brand-navy/10 px-2.5 py-0.5 text-2xs font-semibold uppercase tracking-wide text-brand-navy dark:bg-neutral-700 dark:text-neutral-200">
              {edit.source === 'workspace' ? 'Team default' : 'Personalized'}
            </span>
          )}
          {!editing ? (
            <Button unstyled type="button" onClick={edit.start}
              className={`${tbtn} border-neutral-200 bg-white text-neutral-700 hover:border-brand-navy hover:text-brand-navy dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-300`}>
              <Pencil className="h-3.5 w-3.5" aria-hidden="true" />Customize
            </Button>
          ) : (
            <>
              <AddWidgetMenu addable={addable} onAdd={edit.add} onNew={() => setPickerOpen(true)} />
              <Button unstyled type="button" onClick={edit.reset}
                className={`${tbtn} border-neutral-200 bg-white text-neutral-600 hover:border-semantic-danger hover:text-semantic-danger dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-400`}>
                <RotateCcw className="h-3.5 w-3.5" aria-hidden="true" />Reset to default
              </Button>
              <Button unstyled type="button" onClick={edit.cancel}
                className={`${tbtn} border-neutral-200 bg-white text-neutral-600 hover:bg-neutral-100 dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-400`}>
                Cancel
              </Button>
              {edit.canTemplate && (
                <Button unstyled type="button" onClick={edit.saveTemplate}
                  title="Apply this layout to everyone in the workspace who hasn't personalized their own"
                  className={`${tbtn} border-brand-navy bg-white text-brand-navy hover:bg-brand-navy/10 dark:border-neutral-600 dark:bg-neutral-800 dark:text-neutral-200`}>
                  <Users className="h-3.5 w-3.5" aria-hidden="true" />Set as team default
                </Button>
              )}
              <Button unstyled type="button" onClick={edit.save}
                className={`${tbtn} border-brand-navy bg-brand-navy text-white hover:bg-brand-navy-tint`}>
                <Check className="h-3.5 w-3.5" aria-hidden="true" />Save for me
              </Button>
            </>
          )}
        </div>
      )}
      <TodayCanvas
        layout={shown} registry={fullRegistry} ctx={fullCtx} editMode={editing}
        onMoveUp={edit?.moveUp} onMoveDown={edit?.moveDown}
        onCycleSpan={edit?.cycleSpan} onRemove={edit?.remove} />
      {pickerOpen && tools && (
        <TodayWidgetPicker
          onClose={() => setPickerOpen(false)} onAdd={edit.add}
          metrics={tools.metrics} onPreview={tools.previewWidgetData} />
      )}
    </>
  );
}

