import { Table } from '@/components/works/atoms/table';
import { useState, useEffect, useCallback } from 'react';
import { FileText, FilePlus2, Sparkles, AlertCircle, Trash2, ChevronDown, ChevronUp } from 'lucide-react';
import { Button } from '@/components/works/button';
import { Field } from '@/components/works/field';
import { EmptyState } from '@/components/works/atoms/empty-state';
import { templatesClient, extractionClient } from '@/lib/knowledge-advanced';
import { KnowAiPanel } from '@/components/knowledge/KnowAiPanel';
import { PageLayout } from '@/components/works/templates/page-layout';

// Advanced Knowledge — Document templates + AI structured-data extraction (iteration-20 Cap I).
// Self-fetching like DeveloperWorkspace: the parent supplies workspaceId + an optional toast handler.
// The library lists/creates workspace-scoped templates; the extraction panel turns free-form text into
// a fields table, badged with the AI Control Plane verdict (RB-40 §2 — "AI" vs "Offline" fallback).
export default function KnowledgeTemplatesView({ workspaceId, onUseTemplate, onToast }) {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [form, setForm] = useState({ name: '', category: '', description: '', body: '' });
  const [creating, setCreating] = useState(false);

  const [text, setText] = useState('');
  const [extraction, setExtraction] = useState(null);
  const [extracting, setExtracting] = useState(false);
  const [expandedId, setExpandedId] = useState(null);

  const notify = useCallback((msg, kind) => { if (onToast) onToast(msg, kind); }, [onToast]);

  const load = useCallback(() => {
    if (!workspaceId) { setLoading(false); return; }
    setLoading(true);
    setError(null);
    templatesClient.list(workspaceId)
      .then((data) => setTemplates(Array.isArray(data) ? data : []))
      .catch((e) => setError(e.message || 'Could not load templates.'))
      .finally(() => setLoading(false));
  }, [workspaceId]);

  useEffect(() => { load(); }, [load]);

  const createTemplate = useCallback(() => {
    if (!form.name.trim()) { notify('A template name is required.', 'error'); return; }
    setCreating(true);
    templatesClient.create(workspaceId, form)
      .then((created) => {
        setTemplates((prev) => [...prev, created]);
        setForm({ name: '', category: '', description: '', body: '' });
        notify('Template created.', 'success');
      })
      .catch((e) => notify(e.message || 'Could not create template.', 'error'))
      .finally(() => setCreating(false));
  }, [workspaceId, form, notify]);

  const deleteTemplate = useCallback((id) => {
    templatesClient.remove(workspaceId, id)
      .then(() => {
        setTemplates((prev) => prev.filter((t) => t.id !== id));
        setExpandedId((prev) => (prev === id ? null : prev));
        notify('Template deleted.', 'success');
      })
      .catch((e) => notify(e.message || 'Could not delete template.', 'error'));
  }, [workspaceId, notify]);

  const runExtract = useCallback(() => {
    if (!text.trim()) { notify('Enter some text to extract from.', 'error'); return; }
    setExtracting(true);
    extractionClient.extract(workspaceId, text)
      .then((res) => setExtraction(res))
      .catch((e) => notify(e.message || 'Could not extract fields.', 'error'))
      .finally(() => setExtracting(false));
  }, [workspaceId, text, notify]);

  return (
    <PageLayout header={null} className="flex h-full flex-col">
      <div className="mb-5">
        <h1 className="text-2xl font-bold text-brand-navy dark:text-white">Advanced Knowledge</h1>
        <p className="text-sm text-neutral-600 dark:text-neutral-400">
          Reusable document templates and AI structured-data extraction.
        </p>
      </div>

      {workspaceId && (
        <div className="mb-6">
          <KnowAiPanel workspaceId={workspaceId} />
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* ── Templates library ── */}
        <section className="lg:col-span-2" aria-labelledby="templates-heading">
          <h2 id="templates-heading" className="text-xl font-semibold text-neutral-900 dark:text-neutral-100 mb-3">
            Document templates
          </h2>
          {loading ? (
            <div className="space-y-2" aria-hidden="true">
              {[0, 1, 2].map((i) => (
                <div key={i} className="h-16 rounded-lg animate-pulse bg-neutral-100 dark:bg-neutral-800" />
              ))}
            </div>
          ) : error ? (
            <div className="flex items-start gap-2 rounded-lg border border-semantic-danger/30 bg-semantic-danger/5 p-4 text-sm text-semantic-danger" role="alert">
              <AlertCircle className="h-5 w-5 flex-shrink-0" aria-hidden="true" />
              <span>{error}</span>
            </div>
          ) : templates.length === 0 ? (
            <EmptyState icon={FileText} title="No templates yet"
              subtitle="Create a reusable template with {{placeholders}} that authors start new articles from." />
          ) : (
            <ul className="space-y-2">
              {templates.map((t) => (
                <li key={t.id}
                  className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg p-4">
                  <div className="flex items-start justify-between gap-3">
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2">
                        {t.category && (
                          <span className="text-xs font-bold px-1.5 py-0.5 rounded bg-brand-navy/10 text-brand-navy">{t.category}</span>
                        )}
                        <span className="font-semibold text-sm text-neutral-900 dark:text-neutral-100 truncate">{t.name}</span>
                      </div>
                      {t.description && <p className="text-xs text-neutral-500 mt-1">{t.description}</p>}
                    </div>
                    <div className="flex items-center gap-1 flex-shrink-0">
                      {t.body && (
                        <Button unstyled
                          type="button"
                          onClick={() => setExpandedId((prev) => (prev === t.id ? null : t.id))}
                          aria-expanded={expandedId === t.id}
                          className="flex items-center gap-0.5 text-xs text-neutral-500 hover:text-brand-navy px-1.5 py-1 rounded focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40"
                        >
                          {expandedId === t.id
                            ? <><ChevronUp aria-hidden="true" className="h-3 w-3" />Hide</>
                            : <><ChevronDown aria-hidden="true" className="h-3 w-3" />Body</>}
                        </Button>
                      )}
                      {onUseTemplate && (
                        <Button variant="secondary" size="sm" onClick={() => onUseTemplate(t)}>Use</Button>
                      )}
                      <Button unstyled
                        type="button"
                        onClick={() => deleteTemplate(t.id)}
                        aria-label={`Delete template "${t.name}"`}
                        className="w-7 h-7 rounded flex items-center justify-center text-neutral-400 hover:text-semantic-danger focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40"
                      >
                        <Trash2 aria-hidden="true" className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  </div>
                  {expandedId === t.id && t.body && (
                    <pre className="mt-3 text-xs font-mono bg-neutral-50 dark:bg-neutral-900/50 border border-neutral-100 dark:border-neutral-800 rounded-md p-3 overflow-x-auto whitespace-pre-wrap text-neutral-700 dark:text-neutral-300 max-h-48">
                      {t.body}
                    </pre>
                  )}
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* ── Create template ── */}
        <section className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl p-4 h-fit"
          aria-labelledby="new-template-heading">
          <h2 id="new-template-heading" className="font-semibold text-sm mb-3 text-neutral-900 dark:text-neutral-100 flex items-center gap-1.5">
            <FilePlus2 className="h-4 w-4" aria-hidden="true" /> New template
          </h2>
          <div className="space-y-3">
            <Field label="Name">
              <input className="input w-full text-sm" value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })} />
            </Field>
            <Field label="Category">
              <input className="input w-full text-sm" placeholder="RUNBOOK" value={form.category}
                onChange={(e) => setForm({ ...form, category: e.target.value })} />
            </Field>
            <Field label="Description">
              <input className="input w-full text-sm" value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })} />
            </Field>
            <Field label="Body (markdown)">
              <textarea className="input w-full text-sm font-mono" rows={5} value={form.body}
                onChange={(e) => setForm({ ...form, body: e.target.value })} />
            </Field>
            <Button variant="action" fullWidth disabled={creating} onClick={createTemplate}>
              {creating ? 'Creating…' : 'Create template'}
            </Button>
          </div>
        </section>
      </div>

      {/* ── Structured extraction ── */}
      <section className="mt-8" aria-labelledby="extract-heading">
        <h2 id="extract-heading" className="text-xl font-semibold text-neutral-900 dark:text-neutral-100 mb-1 flex items-center gap-1.5">
          <Sparkles className="h-5 w-5 text-brand-orange" aria-hidden="true" /> Structured extraction
        </h2>
        <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-3">
          Pull emails, dates, identifiers and key:value fields out of free-form text.
        </p>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <div className="space-y-2">
            <Field label="Text">
              <textarea className="input w-full text-sm" rows={8} value={text}
                placeholder={'Owner: Deepak Pandey\nContact: dev@bcits.in\nDue: 2026-06-07\nTracking WRK-123'}
                onChange={(e) => setText(e.target.value)} />
            </Field>
            <Button variant="action" disabled={extracting} onClick={runExtract}>
              {extracting ? 'Extracting…' : 'Extract fields'}
            </Button>
          </div>
          <div>
            {!extraction ? (
              <EmptyState icon={Sparkles} title="No extraction yet"
                subtitle="Paste structured-looking text and extract its fields. Works offline; AI adds a narrative." />
            ) : (
              <div className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl p-4">
                <div className="flex items-center justify-between mb-3">
                  <span className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">Extracted fields</span>
                  <span className={`text-xs font-bold px-1.5 py-0.5 rounded ${extraction.fallback
                    ? 'bg-neutral-100 dark:bg-neutral-700 text-neutral-600 dark:text-neutral-300'
                    : 'bg-brand-navy/10 text-brand-navy'}`}>
                    {extraction.fallback ? 'Offline' : `AI · ${extraction.tier}`}
                  </span>
                </div>
                <FieldsTable fields={extraction.fields} />
              </div>
            )}
          </div>
        </div>
      </section>
    </PageLayout>
  );
}

// Renders the extracted fields map as a simple two-column table; arrays/objects are flattened to text.
function FieldsTable({ fields }) {
  const entries = Object.entries(fields || {});
  if (entries.length === 0) {
    return <p className="text-sm text-neutral-600 dark:text-neutral-400">No structured fields were found.</p>;
  }
  return (
    <Table className="w-full text-sm">
      <tbody>
        {entries.map(([key, value]) => (
          <tr key={key} className="border-b border-neutral-100 dark:border-neutral-700 last:border-0">
            <th scope="row" className="text-left align-top py-1.5 pr-3 font-medium text-neutral-700 dark:text-neutral-300 whitespace-nowrap">{key}</th>
            <td className="py-1.5 text-neutral-900 dark:text-neutral-100 font-mono break-words">{formatValue(value)}</td>
          </tr>
        ))}
      </tbody>
    </Table>
  );
}

function formatValue(value) {
  if (Array.isArray(value)) return value.join(', ');
  if (value && typeof value === 'object') {
    return Object.entries(value).map(([k, v]) => `${k}: ${v}`).join(' · ');
  }
  return String(value);
}

import { useEffect, useState, useCallback, useRef } from 'react';
import { PageLayout } from '@/components/works/templates/page-layout';
import { Package, Plug, Check, Trash2, AlertCircle } from 'lucide-react';
import { Button } from '@/components/works/button';
import { AsyncBoundary } from '@/components/works/atoms/async-boundary';
import { EmptyState } from '@/components/works/atoms/empty-state';
import { marketplaceClient, parseScopes } from '@/lib/marketplace';

// App Marketplace view (iteration 20, Cap R). Browse the global catalog, install extensions with an
// explicit scope-approval step (permission scoping — granted ⊆ requested), and manage installed
// extensions (enable/disable, uninstall). Self-fetching: the catalog and installs are loaded in an
// effect, keyed by workspaceId. Loading / empty / error states per RB-30 §6; keyboard operable.
export default function MarketplaceView({ workspaceId }) {
  const [listings, setListings] = useState([]);
  const [installed, setInstalled] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [pending, setPending] = useState(null); // listing being installed (scope-approval open)
  const [approvedScopes, setApprovedScopes] = useState([]);
  const dialogCloseRef = useRef(null);

  const closeDialog = useCallback(() => { setPending(null); setApprovedScopes([]); }, []);

  // Move focus into the scope-approval dialog when it opens and close it on Escape (keyboard
  // operability + focus management, RB-30 §6).
  useEffect(() => {
    if (!pending) return undefined;
    if (dialogCloseRef.current && typeof dialogCloseRef.current.focus === 'function') {
      dialogCloseRef.current.focus();
    }
    const onKey = (e) => { if (e.key === 'Escape') closeDialog(); };
    if (typeof document !== 'undefined') document.addEventListener('keydown', onKey);
    return () => { if (typeof document !== 'undefined') document.removeEventListener('keydown', onKey); };
  }, [pending, closeDialog]);

  const load = useCallback(async () => {
    if (!workspaceId) { setLoading(false); return; }
    setLoading(true);
    setError(null);
    try {
      const [cat, inst] = await Promise.all([
        marketplaceClient.listings(workspaceId),
        marketplaceClient.installed(workspaceId),
      ]);
      setListings(Array.isArray(cat) ? cat : []);
      setInstalled(Array.isArray(inst) ? inst : []);
    } catch (e) {
      setError(e.message || 'Failed to load the marketplace.');
    } finally {
      setLoading(false);
    }
  }, [workspaceId]);

  useEffect(() => { load(); }, [load]);

  const installedListingIds = new Set(installed.map((i) => i.listingId));

  function beginInstall(listing) {
    const scopes = parseScopes(listing.requestedScopes);
    setPending(listing);
    setApprovedScopes(scopes); // default: approve all requested scopes
  }

  function toggleScope(scope) {
    setApprovedScopes((prev) =>
      prev.includes(scope) ? prev.filter((s) => s !== scope) : [...prev, scope]);
  }

  async function confirmInstall() {
    if (!pending) return;
    try {
      await marketplaceClient.install(workspaceId, {
        listingId: pending.id,
        grantedScopes: approvedScopes,
      });
      closeDialog();
      await load();
    } catch (e) {
      setError(e.message || 'Install failed.');
    }
  }

  async function toggleEnabled(ext) {
    try {
      await marketplaceClient.setEnabled(workspaceId, ext.id, !ext.enabled);
      await load();
    } catch (e) {
      setError(e.message || 'Could not update the extension.');
    }
  }

  async function uninstall(ext) {
    try {
      await marketplaceClient.uninstall(workspaceId, ext.id);
      await load();
    } catch (e) {
      setError(e.message || 'Uninstall failed.');
    }
  }

  return (
    <PageLayout
      title="App Marketplace"
      description="Install third-party extensions into your workspace. You approve exactly which permissions each extension may use."
      width="dashboard"
    >

      {error && (
        <div role="alert" className="flex items-start gap-2 bg-semantic-danger/10 border border-semantic-danger/30 text-semantic-danger rounded-lg px-4 py-3 mb-4 text-sm">
          <AlertCircle className="h-4 w-4 mt-0.5 flex-shrink-0" aria-hidden="true" />
          <span>{error}</span>
        </div>
      )}

      <AsyncBoundary
        loading={loading}
        label="Loading marketplace"
        className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"
        skeleton={[0, 1, 2].map((i) => (
          <div key={i} className="h-36 rounded-xl bg-neutral-100 dark:bg-neutral-800 animate-pulse" />
        ))}
      >
        <>
          {/* Installed section */}
          <section aria-labelledby="installed-heading" className="mb-8">
            <h2 id="installed-heading" className="text-xl font-semibold text-neutral-900 mb-3">Installed</h2>
            {installed.length === 0 ? (
              <EmptyState icon={Plug} title="No extensions installed"
                subtitle="Install an extension from the catalog below to extend your workspace." />
            ) : (
              <div className="space-y-2">
                {installed.map((ext) => {
                  const listing = listings.find((l) => l.id === ext.listingId);
                  return (
                    <div key={ext.id}
                      className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-lg p-4 flex items-center gap-4">
                      <Package className="h-5 w-5 text-brand-navy flex-shrink-0" aria-hidden="true" />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-neutral-900 truncate">{listing ? listing.name : ext.listingId}</p>
                        <p className="text-xs text-neutral-600 dark:text-neutral-400 truncate">
                          Scopes: {ext.grantedScopes || 'none'}
                        </p>
                      </div>
                      <span className={`text-xs font-medium px-2 py-0.5 rounded-sm ${ext.enabled ? 'text-semantic-success bg-semantic-success/10' : 'text-neutral-600 bg-neutral-100 dark:bg-neutral-700'}`}>
                        {ext.enabled ? 'Enabled' : 'Disabled'}
                      </span>
                      <Button variant="secondary" size="sm" onClick={() => toggleEnabled(ext)}>
                        {ext.enabled ? 'Disable' : 'Enable'}
                      </Button>
                      <Button variant="ghost" size="sm" onClick={() => uninstall(ext)}
                        leftIcon={<Trash2 className="h-3.5 w-3.5" aria-hidden="true" />}
                        aria-label={`Uninstall ${listing ? listing.name : ext.listingId}`}>
                        Uninstall
                      </Button>
                    </div>
                  );
                })}
              </div>
            )}
          </section>

          {/* Catalog section */}
          <section aria-labelledby="catalog-heading">
            <h2 id="catalog-heading" className="text-xl font-semibold text-neutral-900 mb-3">Catalog</h2>
            {listings.length === 0 ? (
              <EmptyState icon={Package} title="No extensions available"
                subtitle="The marketplace catalog is empty right now. Check back soon." />
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {listings.map((l) => {
                  const isInstalled = installedListingIds.has(l.id);
                  return (
                    <div key={l.id}
                      className="bg-white dark:bg-neutral-800 border border-neutral-200 dark:border-neutral-700 rounded-xl p-5 flex flex-col">
                      <div className="flex items-center gap-2 mb-2">
                        <Package className="h-5 w-5 text-brand-navy" aria-hidden="true" />
                        <h3 className="text-base font-semibold text-neutral-900 truncate">{l.name}</h3>
                      </div>
                      <p className="text-sm text-neutral-600 dark:text-neutral-400 flex-1 mb-3">{l.summary}</p>
                      <div className="flex items-center justify-between text-xs text-neutral-600 dark:text-neutral-400 mb-3">
                        <span>{l.publisher}</span>
                        {l.version && <span className="font-mono">v{l.version}</span>}
                      </div>
                      {isInstalled ? (
                        <span className="inline-flex items-center gap-1.5 text-sm font-medium text-semantic-success">
                          <Check className="h-4 w-4" aria-hidden="true" /> Installed
                        </span>
                      ) : (
                        <Button variant="action" size="sm" onClick={() => beginInstall(l)}>
                          Install
                        </Button>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </section>
        </>
      </AsyncBoundary>

      {/* Scope-approval dialog */}
      {pending && (
        <div className="fixed inset-0 z-modal flex items-center justify-center bg-brand-navy/40 p-4"
          role="dialog" aria-modal="true" aria-labelledby="scope-dialog-title">
          <div className="bg-white dark:bg-neutral-800 rounded-xl border border-neutral-200 dark:border-neutral-700 p-6 w-full max-w-md">
            <h2 id="scope-dialog-title" className="text-xl font-semibold text-neutral-900 mb-1">
              Install {pending.name}
            </h2>
            <p className="text-sm text-neutral-600 dark:text-neutral-400 mb-4">
              Approve the permissions this extension may use. Only the scopes you approve will be granted.
            </p>
            <fieldset className="space-y-2 mb-5">
              <legend className="sr-only">Requested permissions</legend>
              {parseScopes(pending.requestedScopes).map((scope) => (
                <label key={scope} className="flex items-center gap-2 text-sm text-neutral-900 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={approvedScopes.includes(scope)}
                    onChange={() => toggleScope(scope)}
                    className="rounded-sm border-neutral-400 text-brand-navy focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40"
                  />
                  <span className="font-mono text-xs">{scope}</span>
                </label>
              ))}
              {parseScopes(pending.requestedScopes).length === 0 && (
                <p className="text-sm text-neutral-600 dark:text-neutral-400">This extension requests no permissions.</p>
              )}
            </fieldset>
            <div className="flex items-center justify-end gap-2">
              <Button ref={dialogCloseRef} variant="secondary" size="sm" onClick={closeDialog}>
                Cancel
              </Button>
              <Button variant="action" size="sm" onClick={confirmInstall}>
                Install with {approvedScopes.length} scope{approvedScopes.length !== 1 ? 's' : ''}
              </Button>
            </div>
          </div>
        </div>
      )}
    </PageLayout>
  );
}

import { useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { CheckCircle2, ChevronRight, Layers, Bug, Shuffle, AlertTriangle, X } from 'lucide-react';
import { Button } from '@/components/works/button';
import { useWorkspaceSetup } from '@/hooks/queries/useWorkspaceSetup';
import { workspaceSetupKeys } from '@/hooks/queries/keys';
import { configClient } from '@/lib/customization';
import { cn } from '@/lib/utils';

// ── Template card data ────────────────────────────────────────────────────────

const TEMPLATE_META = {
  'TPL-ONBOARD-SCRUM': {
    icon: Layers,
    color: 'text-brand-navy',
    bg: 'bg-brand-navy/10',
    tagline: 'Sprint-based delivery with backlogs, stories and velocity tracking.',
  },
  'TPL-ONBOARD-KANBAN': {
    icon: Shuffle,
    color: 'text-semantic-success',
    bg: 'bg-semantic-success/10',
    tagline: 'Continuous-flow board — cards move at their own pace with no sprint pressure.',
  },
  'TPL-ONBOARD-BUG': {
    icon: Bug,
    color: 'text-semantic-danger',
    bg: 'bg-semantic-danger/10',
    tagline: 'Defect lifecycle — triage, reproduce, fix and verify bugs end to end.',
  },
  'TPL-ONBOARD-RAID': {
    icon: AlertTriangle,
    color: 'text-semantic-warning',
    bg: 'bg-semantic-warning/10',
    tagline: 'RAID log — track risks, assumptions, issues and dependencies.',
  },
};

// ── Step progress dots ────────────────────────────────────────────────────────

function Steps({ current, total }) {
  return (
    <div className="flex items-center gap-2" aria-label={`Step ${current + 1} of ${total}`}>
      {Array.from({ length: total }, (_, i) => (
        <div key={i}
          className={cn(
            'h-1.5 rounded-full transition-all duration-base',
            i < current ? 'w-6 bg-brand-navy' : i === current ? 'w-6 bg-brand-orange' : 'w-3 bg-neutral-200',
          )}
        />
      ))}
    </div>
  );
}

// ── Step 1: Choose a workflow template ────────────────────────────────────────

function ChooseTemplate({ templates, onSelect, applying, selected }) {
  return (
    <div className="space-y-4">
      <p className="text-sm text-neutral-600">
        Pick a workflow that matches how your team works. You can change it any time from Settings.
      </p>
      <ul className="grid gap-3 sm:grid-cols-2">
        {templates.map((t) => {
          const meta = TEMPLATE_META[t.id] ?? {};
          const Icon = meta.icon ?? Layers;
          const isSelected = selected === t.id;
          return (
            <li key={t.id} className="relative">
              {/* eslint-disable-next-line works-view/no-raw-button -- card-button pattern: full-card interactive affordance, no Button variant fits */}
              <button
                type="button"
                disabled={applying}
                onClick={() => onSelect(t.id)}
                aria-pressed={isSelected}
                className={cn(
                  'w-full rounded-xl border p-4 text-left transition-all duration-fast',
                  'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-navy-tint/40',
                  'hover:border-brand-navy/40 active:translate-y-px disabled:opacity-50',
                  isSelected
                    ? 'border-brand-navy bg-brand-navy/5 ring-1 ring-brand-navy'
                    : 'border-neutral-200 bg-white dark:border-neutral-700 dark:bg-neutral-800',
                )}
              >
                <span className="flex items-start gap-3">
                  <span className={cn('mt-0.5 rounded-lg p-2', meta.bg ?? 'bg-neutral-100')}>
                    <Icon className={cn('h-4 w-4', meta.color ?? 'text-neutral-600')} aria-hidden="true" />
                  </span>
                  <span>
                    <span className="block text-sm font-semibold text-neutral-900 dark:text-neutral-100">
                      {t.name}
                    </span>
                    <span className="mt-0.5 block text-xs text-neutral-500">
                      {meta.tagline ?? t.description}
                    </span>
                  </span>
                </span>
              </button>
              {isSelected && (
                <CheckCircle2
                  className="pointer-events-none absolute right-3 top-3 h-4 w-4 text-brand-navy"
                  aria-hidden="true"
                />
              )}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

// ── Step 2: Completeness checklist ────────────────────────────────────────────

function ChecklistStep({ steps, score, onCreateItem, onInvite, onDone }) {
  return (
    <div className="space-y-5">
      <div className="flex items-center gap-4">
        <div className="relative h-14 w-14 flex-shrink-0">
          <svg viewBox="0 0 36 36" className="-rotate-90 h-14 w-14" aria-hidden="true">
            <circle cx="18" cy="18" r="15.9" fill="none" pathLength="100"
              className="stroke-neutral-100 dark:stroke-neutral-700" strokeWidth="3" />
            <circle cx="18" cy="18" r="15.9" fill="none" pathLength="100"
              className="stroke-brand-orange" strokeWidth="3" strokeLinecap="round"
              strokeDasharray={`${score} 100`} />
          </svg>
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-xs font-bold text-neutral-900 dark:text-neutral-100">{score}%</span>
          </div>
        </div>
        <div>
          <p className="text-sm font-semibold text-neutral-900 dark:text-neutral-100">
            Setup {score === 100 ? 'complete!' : 'in progress'}
          </p>
          <p className="text-xs text-neutral-500">
            Complete these steps to get the most out of bSmart Works.
          </p>
        </div>
      </div>

      <ul className="space-y-2">
        {steps.map((step) => (
          <li key={step.id}
            className={cn(
              'flex items-center justify-between rounded-lg border px-4 py-3 text-sm',
              step.done
                ? 'border-semantic-success/30 bg-semantic-success/5'
                : 'border-neutral-200 bg-white dark:border-neutral-700 dark:bg-neutral-800',
            )}
          >
            <span className="flex items-center gap-3">
              <CheckCircle2 className={cn('h-4 w-4 flex-shrink-0',
                step.done ? 'text-semantic-success' : 'text-neutral-300')}
                aria-hidden="true" />
              <span className={step.done ? 'text-neutral-500 line-through' : 'text-neutral-900 dark:text-neutral-100'}>
                {step.label}
              </span>
            </span>
            {!step.done && step.id === 'first_item' && (
              <Button variant="link" size="sm" rightIcon={ChevronRight} onClick={onCreateItem}>
                Create
              </Button>
            )}
            {!step.done && step.id === 'teammate' && (
              <Button variant="link" size="sm" rightIcon={ChevronRight} onClick={onInvite}>
                Invite
              </Button>
            )}
          </li>
        ))}
      </ul>

      <Button
        variant={score === 100 ? 'action' : 'secondary'}
        fullWidth
        onClick={onDone}
      >
        {score === 100 ? 'Get started →' : 'Skip for now'}
      </Button>
    </div>
  );
}

// ── Root wizard ───────────────────────────────────────────────────────────────

/**
 * First-run onboarding wizard (WI-12).
 *
 * Rendered as a centered modal overlay when a new workspace member's setup status
 * has needsWizard = true. The wizard guides through: (1) choose a workflow template,
 * (2) completeness checklist (create first item, invite teammate).
 *
 * Props:
 *   workspaceId  — the active workspace
 *   onDone       — called when the user finishes or skips the wizard
 *   onCreateItem — called when user clicks "Create" in the checklist
 *   onInvite     — called when user clicks "Invite" in the checklist
 */
export default function OnboardingWizard({ workspaceId, onDone, onCreateItem, onInvite }) {
  const { data: setup } = useWorkspaceSetup(workspaceId);
  const queryClient = useQueryClient();

  const [step, setStep] = useState(0);
  const [applying, setApplying] = useState(false);
  const [selected, setSelected] = useState(null);
  const [error, setError] = useState(null);

  if (!setup?.needsWizard) return null;

  const templates = setup.templates ?? [];
  const steps     = setup.steps ?? [];
  const score     = setup.score ?? 0;

  async function handleTemplateSelect(templateId) {
    setSelected(templateId);
    setError(null);
    setApplying(true);
    try {
      await configClient.applyTemplate(workspaceId, templateId);
      await queryClient.invalidateQueries({ queryKey: workspaceSetupKeys.status(workspaceId) });
      setStep(1);
    } catch {
      setError('Could not apply the template — please try again.');
    } finally {
      setApplying(false);
    }
  }

  const TITLES = ['Choose your workflow', 'Set up your workspace'];
  const TOTAL  = TITLES.length;

  return (
    <div className="fixed inset-0 z-modal flex items-center justify-center bg-neutral-900/60 p-4"
      role="dialog" aria-modal="true" aria-labelledby="wizard-title">
      {/* eslint-disable-next-line works-view/no-inline-card-chrome, works-view/sanctioned-page-widths */}
      <div className="relative w-full max-w-lg overflow-hidden rounded-2xl bg-white shadow-xl dark:bg-neutral-900">

        {/* Header */}
        <div className="flex items-start justify-between border-b border-neutral-100 px-6 py-5 dark:border-neutral-700">
          <div>
            <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-neutral-400">
              Getting started
            </p>
            <h2 id="wizard-title" className="text-xl font-bold text-brand-navy dark:text-white">
              {TITLES[step]}
            </h2>
          </div>
          <Button variant="ghost" size="icon" onClick={onDone} aria-label="Close setup wizard">
            <X className="h-5 w-5" aria-hidden="true" />
          </Button>
        </div>

        {/* Body */}
        <div className="px-6 py-5">
          {step === 0 && (
            <ChooseTemplate
              templates={templates}
              selected={selected}
              applying={applying}
              onSelect={handleTemplateSelect}
            />
          )}
          {step === 1 && (
            <ChecklistStep
              steps={steps}
              score={score}
              onCreateItem={onCreateItem}
              onInvite={onInvite}
              onDone={onDone}
            />
          )}
          {error && (
            <p role="alert" className="mt-3 text-xs text-semantic-danger">{error}</p>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-neutral-100 px-6 py-4 dark:border-neutral-700">
          <Steps current={step} total={TOTAL} />
          {step === 0 && (
            <Button variant="ghost" size="sm" onClick={() => setStep(1)}>
              Skip template
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}

